suppressMessages(library(dplyr));setwd("/Users/hanno/Documents/GitHub/german_election_data")
w<-readRDS("data/state_elections/final/ltw_wkr_unharm.rds");s<-readRDS("data/state_elections/final/state_unharm.rds")
print(table(w$stimme,useNA="a"))
ws<-w%>%group_by(state,election_year,stimme)%>%summarise(wev=sum(eligible_voters,na.rm=T),wnv=sum(number_voters,na.rm=T),wvv=sum(valid_votes,na.rm=T),nw=n(),.groups="drop")
ss<-s%>%group_by(state,election_year)%>%summarise(sev=sum(eligible_voters,na.rm=T),snv=sum(number_voters,na.rm=T),svv=sum(valid_votes,na.rm=T),nm=n(),.groups="drop")
x<-inner_join(ws,ss,by=c("state","election_year"))%>%mutate(dev=wev/sev-1,dnv=wnv/snv-1,dvv=wvv/svv-1)
cat("wkr state-years:",n_distinct(paste(w$state,w$election_year)),"matched to state_unharm:",n_distinct(paste(x$state,x$election_year)),"\n")
print(as.data.frame(x%>%filter(abs(dev)>.01|abs(dnv)>.01|abs(dvv)>.01)%>%select(state,election_year,stimme,nw,nm,wev,sev,dev,dnv,dvv)),digits=3)
print(as.data.frame(anti_join(distinct(w,state,election_year),ss,by=c("state","election_year"))))
